head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//회사명변경내역
scwin.vScrenID = "ULDINS90900.xml";
scwin.param1 = "";
scwin.listcount = 0;
scwin.crud = "";
scwin.prevRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 회사명변경내역  조회 한다.
 ***********************************************/
scwin.ins_search = function(isurcd) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS90900_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listInstNmEditInquiry" + "&{P}param01=" + isurcd;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    //ShowWin(grd_Grid); // 그리드명을 표기

};



/********************************************** 
 * 함수명   : ins_process
 * 설명       : 회사명변경내역  저장,수정  한다. screenProcsTpCd 02 저장 screenProcsTpCd 03 수정 
 ***********************************************/
scwin.ins_process = function(screenProcsTpCd) {
    //alert("dts_Out.Text " +dts_Out.Text);
    //alert("dts_Out.ISUR_CD " +dts_Out.NameValue(dts_Out.RowPosition,"ISUR_NM"));


    if ($c.stf.getObjectValue(edt_CHG_DD) == "" || $c.stf.getObjectValue(edt_CHG_DD).indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "변경일"));
        edt_CHG_DD.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_CHG_DD).length == 8) {

    } else {
        $c.win.alert("올바른 날짜를 입력하세요.");
        edt_CHG_DD.focus();
        return;
    }
    if (txb_ISUR_NM.getValue() == "" || txb_ISUR_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "변경전발행기관명"));
        txb_ISUR_NM.focus();
        return;
    }
    if (txb_MEMO_CONTN.getValue() == "" || txb_MEMO_CONTN.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "메모"));
        txb_MEMO_CONTN.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_MEMO_CONTN, 100, "메모")) {
        //txb_MEMO_CONTN.value = "";
        txb_MEMO_CONTN.focus();
        return false;
    }
    if (scwin.listcount == 0) {

    } else {
        if (!$c.cp.isModified(dts_List)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }
        if (screenProcsTpCd == "02") {
            // 등록시 중복체크 
            if (scwin.fn_dup() == false) {
                $c.win.alert("변경일 중복입니다.");
                return;
            }
        }
    }
    trs_save.Action = "/CmmInfoAction.do?method=processInstNmEdit" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_save.Post();
};


/********************************************** 
 * 함수명   : ins_remove
 * 설명       : 회사명변경내역  삭제  한다.
 ***********************************************/
scwin.ins_remove = function() {
    if (dts_List.getTotalRow() == 1) {
        $c.win.alert("정보가 1건입니다. 삭제불가입니다. 수정만 가능합니다.");
        return;
    }
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        //dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ListDelete.insertRow();
        dts_ListDelete.setCellData(1, "SEQ", dts_List.getCellData(dts_List.getRowPosition(), "SEQ"));

        //alert("dts_ListDelete.ISUR_CD "+ dts_ListDelete.NameValue(dts_ListDelete.RowPosition,"ISUR_CD"));

        trs_remove.Action = "/CmmInfoAction.do?method=processInstNmEdit" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_remove.KeyName = "toinb_dataid4";
        trs_remove.KeyValue = "JSP(I:pInput=dts_ListDelete)";
        trs_remove.Post();
    }
};



/********************************************** 
 * 함수명   : fn_new
 * 설명       :  조회버튼 클릭시 신규등록을 위한 dataset 세팅 
 ***********************************************/
scwin.fn_new = function() {
    dts_List.insertRow();
    dts_List.setCellData(dts_List.getRowPosition(), "ISUR_CD", scwin.param1);
    fn_CtrlBtn("insert");
};



/********************************************** 
 * 함수명   : fn_dup
 * 설명       :변경일 중복검사 
 ***********************************************/
scwin.fn_dup = function() {
    var dupcnt = 0;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        //alert(dts_List.NameString(i, "CHG_DD") +" " + getObjectValue(edt_CHG_DD));
        if (dts_List.getCellData(i, "CHG_DD") == $c.stf.getObjectValue(edt_CHG_DD)) {
            dupcnt++;
        }
    }
    //alert("dupcnt " +dupcnt);
    if (eval(dupcnt) < 2) {
        return true;
    } // 중복아님 
    else {
        return false;
    } // 중복 

};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    scwin.listcount = rowcount;
    //CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	
    txb_ISUR_CD.setValue(scwin.param1);
    // 데이터가 없는 경우
    if (rowcount == 0) {
        fn_CtrlBtn("no_data");
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    //CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리 
    fn_CtrlBtn("no_data");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] != undefined) ? arrPar[0] : "");
    }
    scwin.ins_search(scwin.param1);
    $c.stf.showObj(txb_SEQ, false);
};
scwin.btn_save_onclick = function() {
    scwin.ins_process("02");
};
scwin.btn_modify_onclick = function() {
    scwin.ins_process("03");
};
scwin.btn_delete_onclick = function() {
    scwin.ins_remove();
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "회사명변경내역 저장"));
    scwin.ins_search(scwin.param1);
    $c.frame.path("../").ins_detail(scwin.param1);
    //frame.CloseFrame();

};
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
};
scwin.trs_modify_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "회사명변경내역 수정"));
    //frame.CloseFrame();

};
scwin.trs_modify_OnFail = function() {
    alert_tr_error(trs_modify);
};
scwin.trs_remove_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "회사명변경내역 삭제"));
    scwin.ins_search(scwin.param1);
    $c.frame.path("../").ins_detail(scwin.param1);
    //frame.CloseFrame();

};
scwin.trs_remove_OnFail = function() {
    alert_tr_error(trs_remove);
};
scwin.img_CHG_DD_onclick = function() {
    popUpCalendar2(edt_CHG_DD);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {

};
scwin.btn_new_onclick = function() {
    scwin.fn_new();
};
scwin.dts_List_OnRowPosChanged = function(row) {
    dts_List.undoRow(scwin.prevRow);
    scwin.prevRow = row;
    fn_CtrlBtn("update");
};
